INSERT INTO lr_questions (section_id, qid, preptest, section, question_number, question_type, stimulus, prompt, correct_choice, is_explained, source_note) SELECT s.id, $batch02$PT146-S1-Q7$batch02$, 146, 1, 7, $batch02$Flaw$batch02$, $batch02$Editorialist: The city council is considering increasing the amount of air traffic allowed at the airport beyond its original design capacity. Several council members say that this increase would not decrease safety as it would be accompanied by the purchase of the latest safety technology. But in fact it would decrease safety. Numerous studies conducted 30 years ago show that safety was reduced at every airport where the permitted level of traffic was increased beyond the airport’s original design capacity, even when those airports made use of the latest safety technology.$batch02$, $batch02$Which one of the following most accurately describes a flaw in the editorialist’s argument?$batch02$, $batch02$B$batch02$, true, $batch02$Batch 02 approved 2026-10-01; question text from local bank.$batch02$ FROM lr_sections s WHERE s.preptest=146 AND s.section=1 AND NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch02$PT146-S1-Q7$batch02$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch02$A$batch02$, $batch02$The argument draws a conclusion on the basis of a general statement that has in turn been inferred from a very limited number of particular instances.$batch02$, $batch02$Not Sampling$batch02$, false FROM lr_questions q WHERE q.qid=$batch02$PT146-S1-Q7$batch02$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch02$A$batch02$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch02$B$batch02$, $batch02$The argument fails to consider the possibility that whether an airport can allow more air traffic than it was originally designed for without reducing safety depends largely on what the latest technology is.$batch02$, $batch02$Correct$batch02$, true FROM lr_questions q WHERE q.qid=$batch02$PT146-S1-Q7$batch02$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch02$B$batch02$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch02$C$batch02$, $batch02$The argument fails to consider the possibility that the city council members who support the increase are aware of the studies that were conducted 30 years ago.$batch02$, $batch02$Out of Scope$batch02$, false FROM lr_questions q WHERE q.qid=$batch02$PT146-S1-Q7$batch02$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch02$C$batch02$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch02$D$batch02$, $batch02$The argument confuses an absence of evidence for the claim that the airport can safely permit air traffic in excess of its original design capacity with the existence of evidence against this claim.$batch02$, $batch02$Bad Description$batch02$, false FROM lr_questions q WHERE q.qid=$batch02$PT146-S1-Q7$batch02$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch02$D$batch02$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch02$E$batch02$, $batch02$The argument fails to consider that a slight increase in safety risks might be acceptable if it yields overriding benefits of another kind.$batch02$, $batch02$Out of Scope$batch02$, false FROM lr_questions q WHERE q.qid=$batch02$PT146-S1-Q7$batch02$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch02$E$batch02$) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch02$PT146-S1-Q7$batch02$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch02$Conclusion$batch02$, $batch02$Increasing traffic would decrease safety, even with the latest technology.$batch02$), (1, $batch02$Evidence$batch02$, $batch02$Studies from 30 years ago found safety fell at every airport that exceeded design capacity, even with the latest technology of that time.$batch02$), (2, $batch02$Evaluate$batch02$, $batch02$"The latest safety technology" 30 years ago is not the latest technology today. Phones 30 years ago could not stream video; that says nothing about phones now. The studies tell us what the technology of that era could handle. The council members are talking about today's technology. The comparison across 30 years needs the two to be alike, and they may not be.$batch02$), (3, $batch02$Goal$batch02$, $batch02$Look for the difference between then and now: the technology has changed.$batch02$)) v(position,label,body) WHERE q.qid=$batch02$PT146-S1-Q7$batch02$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch02$A$batch02$, $batch02$The studies were "numerous" and covered "every airport" that exceeded capacity. Nothing suggests too few cases. The problem is their age.$batch02$), ($batch02$B$batch02$, $batch02$If safety at higher traffic depends heavily on *which* technology is in use, results with 30-year-old technology do not predict results with today's. The editorialist treats "latest" then as the same as "latest" now.$batch02$), ($batch02$C$batch02$, $batch02$Whether council members know about the studies does not affect whether the studies support the conclusion.$batch02$), ($batch02$D$batch02$, $batch02$The editorialist does cite evidence against the claim: the studies. The weakness is that the evidence is outdated, not that the argument mistakes a lack of evidence for evidence.$batch02$), ($batch02$E$batch02$, $batch02$The conclusion is only that safety would decrease. Whether a decrease is worth it is a separate question the editorialist never raises.$batch02$)) v(letter,body) WHERE q.qid=$batch02$PT146-S1-Q7$batch02$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
